<?php require 'conexion.php';$u=authUser($pdo);$d=body();$nombre=trim($d['nombre']??$u['nombre']);$celular=trim($d['celular']??$u['celular']);$lat=$d['lat']??$u['lat'];$lng=$d['lng']??$u['lng'];$pdo->prepare('UPDATE usuarios SET nombre=?,celular=?,lat=?,lng=? WHERE id=?')->execute([$nombre,$celular,$lat,$lng,$u['id']]);$u['nombre']=$nombre;$u['celular']=$celular;$u['lat']=$lat;$u['lng']=$lng;out(['ok'=>true,'usuario'=>$u]);
